import{_ as a,o as e,c as r,a5 as l}from"./chunks/framework.bIR-4glx.js";const b=JSON.parse('{"title":"CEFR 目标与英语能力自测","description":"用 A1-C2 的“能做什么”描述诊断听说读写起点，并把水平转成可检查的 7 天、30 天与 12 周任务。","frontmatter":{"title":"CEFR 目标与英语能力自测","description":"用 A1-C2 的“能做什么”描述诊断听说读写起点，并把水平转成可检查的 7 天、30 天与 12 周任务。","updated":"2026-10-06T00:00:00.000Z"},"headers":[],"relativePath":"threads/part-1/0-cefr.md","filePath":"threads/part-1/0-cefr.md","lastUpdated":1791244800000}'),d={name:"threads/part-1/0-cefr.md"};function i(o,t,h,n,s,c){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="cefr-目标与英语能力自测" tabindex="-1">CEFR 目标与英语能力自测 <a class="header-anchor" href="#cefr-目标与英语能力自测" aria-label="Permalink to &quot;CEFR 目标与英语能力自测&quot;">​</a></h1><p>CEFR（欧洲语言共同参考框架）描述的是<strong>在具体情境中能完成什么语言任务</strong>，不是某个 App 的积分，也不是一个固定词汇量。下面是基于欧洲委员会全球量表的简化自测；它适合确定训练起点，不能替代正式考试。</p><h2 id="本章速览" tabindex="-1">本章速览 <a class="header-anchor" href="#本章速览" aria-label="Permalink to &quot;本章速览&quot;">​</a></h2><ul><li>分别为听、说、读、写保存未经修饰的基线；</li><li>把 A1–C2 的方向翻译成具体场景、任务、质量门槛和期限；</li><li>用 7 天、30 天和 12 周的节奏安排练习，而不是追逐一个平均等级；</li><li>用相同条件、平行任务和外部反馈复测，决定下一项变量。</li></ul><h2 id="a1-c2-我能做到什么" tabindex="-1">A1-C2：我能做到什么 <a class="header-anchor" href="#a1-c2-我能做到什么" aria-label="Permalink to &quot;A1-C2：我能做到什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>等级</th><th>可观察的综合表现</th></tr></thead><tbody><tr><td>A1</td><td>能理解和使用非常常见的表达；在对方说得慢、愿意帮助时进行简单互动。</td></tr><tr><td>A2</td><td>能处理个人信息、购物、地点、工作等熟悉主题的直接交流。</td></tr><tr><td>B1</td><td>能理解熟悉主题的主要意思；在旅行与日常场景中应对，并简单说明经历、计划和理由。</td></tr><tr><td>B2</td><td>能理解具体或抽象复杂文本的主要观点；与熟练使用者较自然地互动，并清楚表达立场。</td></tr><tr><td>C1</td><td>能理解要求高、篇幅长的材料并把握隐含意义；在学术、职业和社会场景中灵活表达。</td></tr><tr><td>C2</td><td>几乎能轻松理解听到或读到的内容；能综合不同来源、重构论点并精确表达细微差别。</td></tr></tbody></table><p>来源：<a href="https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale" target="_blank" rel="noreferrer">Council of Europe, CEFR 3.3 Global Scale</a>，访问日期 2026-08-16。上表为便于行动的中文概括，不是官方译文。</p><h2 id="四项能力的快速证据" tabindex="-1">四项能力的快速证据 <a class="header-anchor" href="#四项能力的快速证据" aria-label="Permalink to &quot;四项能力的快速证据&quot;">​</a></h2><p>选一个与你真实生活相关的主题，完成以下任务。不要查词完成第一版，保存原始样本。</p><table tabindex="0"><thead><tr><th>能力</th><th>10–20 分钟任务</th><th>检查点</th></tr></thead><tbody><tr><td>听力</td><td>听 2–4 分钟材料，写下主旨、3 个细节，再复述</td><td>主旨、细节、语块边界、漏听原因</td></tr><tr><td>阅读</td><td>读 600–1000 词文章，写五句摘要和一个质疑</td><td>主要观点、证据、推断、生词是否妨碍理解</td></tr><tr><td>口语</td><td>不读稿录 2 分钟，解释经历、观点或流程</td><td>可理解度、停顿、语法、词块、任务是否完成</td></tr><tr><td>写作</td><td>20 分钟写 180–250 词邮件、说明或短文</td><td>目的、结构、论证、准确度、修订能力</td></tr></tbody></table><p>把样本和自评写入 <a href="./../../templates/english-diagnostic">英语能力诊断</a>。如果四项差异很大，分别定级，不要强行取平均值。</p><h2 id="别让四项平均分遮住协作能力" tabindex="-1">别让四项平均分遮住协作能力 <a class="header-anchor" href="#别让四项平均分遮住协作能力" aria-label="Permalink to &quot;别让四项平均分遮住协作能力&quot;">​</a></h2><p>听、读、说、写是必要的入口，但真实学习和工作还经常要求你把信息交给别人、在异步对话中推进事情，并在误解出现时及时修复。这些是<strong>任务维度</strong>，不是要在 A1–C2 之外再增加一个等级；可以在同一张诊断表里单独保存证据。</p><table tabindex="0"><thead><tr><th>任务维度</th><th>10–15 分钟样本</th><th>通过证据</th></tr></thead><tbody><tr><td>转述与调解</td><td>读两段立场不同的短材料，用英文说明各自的主张、差异和仍然未知的地方</td><td>听众能分清两方观点、你的转述和你的推断，没有把冲突润色成一致</td></tr><tr><td>在线互动</td><td>在一个真实或模拟的异步线程里，写一条进展、一个阻塞和下一步</td><td>对方无需开会就知道谁负责、什么时候继续、还缺什么信息</td></tr><tr><td>误解修复</td><td>在对话中请求澄清，再用自己的话复述共识和未决问题</td><td>对方确认你的复述准确，下一步动作没有因为猜测而改变</td></tr></tbody></table><p>如果岗位、课程或家庭协作很少涉及其中一项，可以暂时不测；如果它正是现实中的高风险环节，就不要用口语或写作分数替代它。需要更具体的岗位样本时，进入<a href="./8-job-search-english">求职英语篇</a>，把这些维度放回真实岗位描述和证据卡。</p><h2 id="从级别到目标" tabindex="-1">从级别到目标 <a class="header-anchor" href="#从级别到目标" aria-label="Permalink to &quot;从级别到目标&quot;">​</a></h2><p>一个有效目标应同时包含：<strong>场景、任务、质量门槛、期限和证据</strong>。</p><blockquote><p>12 周后，我能在一次 5 分钟工作汇报中说明背景、进展和风险；听众无需切换中文也能复述要点；我保存第 1、4、8、12 周录音和反馈表。</p></blockquote><p>“从 B1 到 B2”可以作为方向，但不能单独作为训练目标。进阶通常不是匀速的，也无法由学习小时数保证。</p><p>若真实目标是海外岗位或远程面试，不要把 B1、B2 或 C1 写成统一录用线。先进入<a href="./8-job-search-english">求职英语篇</a>，用一个真实岗位测试项目说明、陌生追问、互动修复和异步写作，再让分项表现决定下一变量。</p><h2 id="_7-天启动" tabindex="-1">7 天启动 <a class="header-anchor" href="#_7-天启动" aria-label="Permalink to &quot;7 天启动&quot;">​</a></h2><ul><li>第 1 天：完成四项基线，各保存一个未经修饰的样本。</li><li>第 2–5 天：每天选一项，做 25–45 分钟“输入 → 主动回忆 → 输出 → 反馈”。</li><li>第 6 天：重复最弱任务，比较同类错误是否减少。</li><li>第 7 天：填写 <a href="./../../templates/weekly-review">每周复盘</a>，只确定下周一个重点。</li></ul><h2 id="_30-天建立系统" tabindex="-1">30 天建立系统 <a class="header-anchor" href="#_30-天建立系统" aria-label="Permalink to &quot;30 天建立系统&quot;">​</a></h2><ul><li>每周至少完成听、说、读、写各一个可检查任务；重点能力可增加频率。</li><li>建立错误分类：理解、词汇/词块、发音、语法、结构、策略、注意力。</li><li>每周重做一次旧任务或同难度平行任务，比较表现而不是比较感觉。</li><li>第 30 天用同一主题和时长复测，保留前后样本与外部反馈。</li></ul><h2 id="_12-周完成迁移" tabindex="-1">12 周完成迁移 <a class="header-anchor" href="#_12-周完成迁移" aria-label="Permalink to &quot;12 周完成迁移&quot;">​</a></h2><ul><li>第 1–4 周：建立稳定节奏，任务略低于挫败阈值。</li><li>第 5–8 周：增加材料复杂度和时间压力，练习跨主题迁移。</li><li>第 9–11 周：模拟真实考试、会议、演讲、阅读或写作交付。</li><li>第 12 周：完成最终任务，盲评或请真实读者/听众反馈，决定下一周期。</li></ul><h2 id="反馈量表" tabindex="-1">反馈量表 <a class="header-anchor" href="#反馈量表" aria-label="Permalink to &quot;反馈量表&quot;">​</a></h2><p>每项 0–2 分：<code>0=未完成</code>，<code>1=部分完成</code>，<code>2=稳定完成</code>。</p><ol><li><strong>任务完成</strong>：信息和意图是否传达？</li><li><strong>可理解度</strong>：对方能否无需猜测地理解？</li><li><strong>准确与范围</strong>：词汇、语法、发音或拼写是否支持任务？</li><li><strong>组织与流畅</strong>：信息是否连贯，停顿是否破坏交流？</li><li><strong>修订与迁移</strong>：收到反馈后能否改进，并在新任务中复用？</li></ol><p>总分只用于同一个人的纵向比较，不用于给别人贴标签。</p><p>若“准确与范围”持续失分，不要把全部问题统称为“语法差”。先确认错误是否改变时间、参与者、否定、条件或确定性，再用<a href="./grammar">语法篇</a>和<a href="./../../templates/grammar-evidence">语法证据卡</a>追踪一个会影响任务的结构；低影响偏差可以后置。</p><h2 id="把自测带进下一周期" tabindex="-1">把自测带进下一周期 <a class="header-anchor" href="#把自测带进下一周期" aria-label="Permalink to &quot;把自测带进下一周期&quot;">​</a></h2><p>这张量表只描述一次任务中的表现，不替你宣布已经“达到某个等级”。完成自测后，请把结果带进<a href="./../part-3/5-evidence-and-transfer">证据篇：变化要如何被看见</a>：</p><ol><li>保存今天的基线，不要用修订后的版本覆盖它；</li><li>练习后记录即时表现，并写下获得了哪些帮助；</li><li>七天后撤掉最近提示，完成一次延迟保持复测；</li><li>三十天或九十天后更换主题、听众或任务，检查是否发生迁移。</li></ol><p>如果四项能力差异很大，分别追踪它们的证据链。自测的价值不是给自己一个漂亮的标签，而是让下一次练习拥有可以比较的起点。</p><p>需要把四个时间点放在同一页时，使用<a href="./../../templates/evidence-chain">证据链模板</a>，不要只保留最终分数。</p><h2 id="结语-级别只是坐标" tabindex="-1">结语：级别只是坐标 <a class="header-anchor" href="#结语-级别只是坐标" aria-label="Permalink to &quot;结语：级别只是坐标&quot;">​</a></h2><p>一个等级可以告诉你，某项任务大概有多远，却不能告诉你为什么要走，也不能替你走。A2、B1 或 C1 都只是某些条件下的表现描述，不是一个人的上限，更不是值得被喜欢、被信任或被看见的资格证。</p><p>真正的变化往往比等级安静：第一次听懂陌生人的请求，第一次在会议里说完自己的理由，第一次写出一封不需要对方反复猜测的邮件。它们未必让标签立刻改变，却已经让你与世界之间多了一条可以通行的路。</p><p>所以请保存今天的分数，也保存今天的笨拙。下一次回来，不是为了证明自己配得上某个字母，而是看见自己已经能把哪一件事做得更完整。坐标的意义，是帮助人找到路，不是把人钉在原地。</p>',40)])])}const u=a(d,[["render",i]]);export{b as __pageData,u as default};
